		$result = mysqli_query($GLOBALS["___mysqli_ston"], $query) or die( '<pre>' . mysqli_error($GLOBALS["___mysqli_ston"]) . '</pre>' );", "source": "POST 参数 id", "source_kind": "body", "source_name": "id", "tainted_expression": "$_POST['id'] → $id", "sink": "mysqli_query($GLOBALS["___mysqli_ston"], $query)（第 12 行）；SQLite 分支 $sqlite_db_connection->query($query)（第 30 行）", "endpoint": "/042.php", "http_method": "POST", "exploit_chain": [{"step": 1, "location": "042.php:5", "description": "从 POST 请求体读取 id 参数", "data_state": "原始字符串，完全攻击者可控"}, {"step": 2, "location": "042.php:7", "description": "调用 mysqli_real_escape_string 转义", "data_state": "仅转义引号/反斜杠等字符，数字型上下文下不改变注入语义", "bypass_reason": "SQL 语句中 $id 未加引号，属于数字型注入点，转义函数对 OR/UNION/注释符等无过滤作用"}, {"step": 3, "location": "042.php:11", "description": "将 $id 直接拼接进 SELECT 语句", "data_state": "恶意 SQL 片段进入查询字符串"}, {"step": 4, "location": "042.php:12", "description": "mysqli_query 执行拼接后的 SQL", "data_state": "数据库执行攻击者构造的语句"}, {"step": 5, "location": "042.php:21", "description": "将 $id 与查询结果回显到页面", "data_state": "注入结果可被攻击者直接观测"}], "poc": {"description": "向 042.php 提交 id 参数，利用数字型注入改变 WHERE 条件或 UNION 读取数据", "preconditions": ["目标部署了 DVWA 的 SQL Injection 模块（042.php 可访问）", "$_DVWA['SQLI_DB'] 配置为 MYSQL 或 SQLITE 分支之一", "无需认证（若部署在 DVWA 登录后，则需低权限账号）"], "steps": [{"step": 1, "action": "提交布尔型注入验证条件恒真", "request": "POST /042.php HTTP/1.1
